(function(){
  var BASE=36, TMIN=1, TMAX=26, SKEW=38, DAMP=700, INITIAL_BIAS=72, INITIAL_N=128, DELIMITER='-';
  function ucs2decode(str){ var out=[],i=0,l=str.length,val,extra; while(i<l){ val=str.charCodeAt(i++);
    if(val>=0xD800&&val<=0xDBFF&&i<l){ extra=str.charCodeAt(i++); if((extra&0xFC00)===0xDC00){ out.push(((val&0x3FF)<<10)+(extra&0x3FF)+0x10000); continue; } i--; }
    out.push(val); } return out; }
  function ucs2encode(arr){ var out='',i=0,l=arr.length,val; while(i<l){ val=arr[i++];
    if(val>0xFFFF){ val-=0x10000; out+=String.fromCharCode(((val>>>10)&0x3FF)|0xD800); out+=String.fromCharCode((val&0x3FF)|0xDC00); } else out+=String.fromCharCode(val); } return out; }
  function basicToDigit(cp){ if(cp-0x30<0x0A) return cp-0x30+0x1A; if(cp-0x61<0x1A) return cp-0x61; return -1; }
  function digitToBasic(d){ return d<26 ? String.fromCharCode(97+d) : String.fromCharCode(22+d); }
  function adapt(delta,num,first){ var k=0; delta=first?Math.floor(delta/DAMP):delta>>1; delta+=Math.floor(delta/num);
    for(;delta>((BASE-TMIN)*TMAX)>>1;k+=BASE){ delta=Math.floor(delta/(BASE-TMIN)); }
    return Math.floor(k+(BASE-TMIN+1)*delta/(delta+SKEW)); }
  function punyDecode(input){ input=String(input); var n=INITIAL_N,i=0,bias=INITIAL_BIAS,out=[];
    var basic=input.lastIndexOf(DELIMITER); if(basic<0)basic=0;
    for(var j=0;j<basic;j++){ if(input.charCodeAt(j)>=0x80) return {error:'含非 ASCII 基础字符'}; out.push(input.charCodeAt(j)); }
    var idx=basic>0?basic+1:0;
    while(idx<input.length){ var oldi=i, w=1, k=BASE;
      while(true){ var digit=basicToDigit(input.charCodeAt(idx++)); if(digit<0) return {error:'非法字符'}; i+=digit*w;
        var t=(k<=bias+TMIN)?TMIN:((k>=bias+TMAX)?TMAX:k-bias); if(digit<t)break; w*=(BASE-t); k+=BASE; }
      var len=out.length+1; bias=adapt(i-oldi,len,oldi===0); n+=Math.floor(i/len); var ins=i%len; out.splice(ins,0,n); i=ins+1; }
    return {value:out}; }
  function punyEncode(cp){ var out=[], n=INITIAL_N, delta=0, bias=INITIAL_BIAS, b=0;
    for(var i=0;i<cp.length;i++){ if(cp[i]<0x80){ out.push(cp[i]); b++; } }
    var h=b; if(b>0) out.push(DELIMITER.charCodeAt(0));
    while(h<cp.length){ var m=-1; for(var i2=0;i2<cp.length;i2++){ if(cp[i2]>=n && (m<0||cp[i2]<m)) m=cp[i2]; }
      delta+=(m-n)*(h+1); n=m;
      for(var i3=0;i3<cp.length;i3++){ var c=cp[i3]; if(c<n){delta+=1;continue;} if(c===n){ var q=delta;
        for(var k=BASE;;k+=BASE){ var t=(k<=bias+TMIN)?TMIN:((k>=bias+TMAX)?TMAX:k-bias);
          if(q<t) break; out.push(digitToBasic(t+(q-t)%(BASE-t)).charCodeAt(0)); q=Math.floor((q-t)/(BASE-t)); }
        out.push(digitToBasic(q).charCodeAt(0)); delta=adapt(delta,h+1,h===b); delta=0; n++; h++; } }
      delta++; n++; }
    return {value: out.map(function(x){return String.fromCharCode(x);}).join('')}; }
  function toUnicode(domain){ return String(domain).split('.').map(function(label){ if(label.toLowerCase().indexOf('xn--')===0) return ucs2encode(punyDecode(label.slice(4)).value||[]); return label; }).join('.'); }
  function toASCII(domain){ return String(domain).split('.').map(function(label){ if(/[^\x00-\x7f]/.test(label)) return 'xn--'+punyEncode(ucs2decode(label)).value; return label; }).join('.'); }
  var API={toUnicode:toUnicode,toASCII:toASCII,encode:punyEncode,decode:punyDecode};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__PunycodeForge__=API;
})();
